create or replace TABLE SZD_PRODUCTION.ETL.WUP (
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet fuer Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	VW_ID NUMBER(38,0) DEFAULT 0 COMMENT 'ID des Vertriebsweges. Einkaufs-Sicht auf die wup Objekte (Restaurants und Backshops z.Bsp. haben keinen Vertriebsweg)',
	VS_ID NUMBER(38,0) DEFAULT 0 COMMENT 'ID der Vertriebsschiene. Vertriebs-Sicht auf die wup Objekte',
	LAND_ID VARCHAR(8) NOT NULL COLLATE 'en-ci' DEFAULT '  ' COMMENT 'Land, in dem sich der Markt befindet (PL, CZ, DE,..)',
	REGION_ID NUMBER(38,0) COMMENT 'Bundesland, in dem sich der Markt befindet',
	DAT_VON DATE COMMENT 'Eroeffnungsdatum. Muss nicht der 1. Abverkaufstag sein! Format YYYY-MM-DD',
	WUP_TYP_ID NUMBER(38,0) DEFAULT 0 COMMENT 'entspricht der Kennzeichnung der Art des Umschlagplatzes (0: normaler Markt; 1: Lager; 2: Verteilzentrum : -1 System. Neu koennten hier auch noch Mitbewerbermaerkte gefuehrt werden.',
	WUP_NAME_V VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Marktbezeichnung fuer den Vertrieb (aus Hyperion gepflegt)',
	WUP_NAME_E VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Marktbezeichnung fuer den Einkauf (aus SAP gepflegt)',
	WUP_STANDORT VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Ortsbezeichnung',
	WUP_PLZ VARCHAR(40) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Postleitzahl',
	WUP_STR VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Strasse',
	VF_ID NUMBER(38,0) DEFAULT 0 COMMENT 'Vertriebsform (Kaufland, Handelshof,...)',
	VKL_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Verkaufsleiter - kommt aus der Hyperion - Schnittstelle',
	HL_ID NUMBER(38,0) COMMENT 'Hausleiter',
	DAT_BIS DATE DEFAULT CAST('9999-12-31' AS DATE) COMMENT 'Schließungsdatum Format YYYY-MM-DD',
	LEAD_MWST NUMBER(9,3) COMMENT 'Mehrwertsteuersatz - ID (<> Mehrwertsteuersatz!)',
	UEBERNAHME_VON VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'von welchem Mitbewerber wurde der Markt uebernommen',
	BREAKEVENUMSATZ NUMBER(18,2) DEFAULT 0 COMMENT 'Kennzahl, kommt aus Hyperion',
	SYSTEMRENTABILITAET NUMBER(18,2) DEFAULT 0 COMMENT 'Kennzahl, kommt aus Hyperion',
	VERKAUFSFLAECHE NUMBER(18,2) DEFAULT 0 COMMENT 'Verkaufsflaeche des Marktes',
	BETRIEBSFLAECHE NUMBER(18,2) DEFAULT 0 COMMENT 'Betriebsflaeche des Marktes',
	FLEISCHSYSTEM NUMBER(38,0) DEFAULT 0 COMMENT 'Kennzeichnung, ob Fleischtheke vorhanden. Wird z.Zt nicht benutzt',
	PREISKATEGORIE_FOOD NUMBER(38,0) COMMENT 'Preiskategorie Food fuer den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe',
	PREISKATEGORIE_NONFOOD NUMBER(38,0) COMMENT 'Preiskategorie Nonfood fuer den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe',
	SORTKATEGORIE_FOOD NUMBER(38,0) COMMENT 'Sortimentskategorie Food fuer den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe',
	SORTKATEGORIE_NONFOOD NUMBER(38,0) COMMENT 'Preiskategorie Nonfood fuer den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe. Ist z.Zt. immer mit Null gefuellt',
	SONDERMARKT NUMBER(38,0) COMMENT 'wird z.Zt. nicht benutzt',
	REF_WUP_ID NUMBER(38,0) DEFAULT 0 COMMENT 'wird z.Zt. nicht benutzt',
	WM_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Warenmanager ID',
	KASSENTYP VARCHAR(40) DEFAULT '          ' COMMENT 'im Markt benutztes Kassensystem (aus ods_bon_transaction.kassensystem_name)',
	DAT_QBM_UMSTELLUNG DATE COMMENT 'Datum seit wann QBM (oder die aktuelle QBM-Version) im Markt aktiv ist',
	GETRAENKEMARKT_FG NUMBER(38,0) DEFAULT 0 COMMENT 'Getraenkemarkt Flag',
	KUNDENFAKTOR NUMBER(11,10) DEFAULT 1 COMMENT 'Korrekturfaktor zur Ermittlung der Anzahl der Kunden, bei Maerkten mit Getraenkemarkt angewendet',
	VZ_WUP_ID NUMBER(38,0) COMMENT 'Beim wup vom Typ \Lager\ ist hier das Verteilzentrum eingetragen',
	QBM_ID NUMBER(38,0) COMMENT 'Kennzeichnung, ob der Markt ueber ein QBM-System verfuegt (Reklamationsabwicklung)',
	WUP_ID_ALT NUMBER(38,0) COMMENT 'Bei Wechsel der Marktnummer wird hier die alte Marktnummer hinterlegt',
	VERKAUFSORGANISATION_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Organisatorische Einheit, die fuer den Vertrieb bestimmter Produkte oder Dienstleistungen verantwortlich ist, z. B. KL = Kaufland.',
	BUCHUNGSKREIS_ID NUMBER(38,0) COMMENT 'Zuordnung des Buchungskreises zu dem WUP ueber die SAP Quelle T001K und T001. Der Buchungskreis entspricht unter dem Mandanten einer Zusammenfassung von Werken (Hierarchie: Mandant, Buchungskreis, Werk/Betrieb). Bsp: Buchungskreis 282 entspricht Kaufland W',
	DAT_EROEFFNUNG DATE COMMENT '\Echtes\ Eroeffnungsdatum des Marktes. Kann von dat_von abweichen.',
	BEWERTUNGSKREIS_ID VARCHAR(16) COLLATE 'en-ci' DEFAULT '    ' COMMENT 'der Bewertungskreis enthaelt die wup_id. Theoretisch kann auch ein Buchungskreis enthalten sein. ueber den Bewertungskreis wird die Verbindung zum Gleitenden Durchschnittspreis hergestellt',
	WUP_STADT VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Ort aus der Adresse des Marktes',
	HAUPT_WUP_ID NUMBER(38,0) COMMENT 'Hier ist der uebergeordnete wup gespeichert, falls mehrere wup_ids logisch zusammengehoeren (z.Bsp. Restaurant zu Markt)',
	KREISTYP_GRUPPE_ID VARCHAR(16) COLLATE 'en-ci' COMMENT 'Region / Gruppierung Kreistypen',
	DAT_UMSTELLUNG_WAAGE DATE NOT NULL DEFAULT CAST('9999-12-31' AS DATE) COMMENT 'Datum, ab dem die Waagendaten sich im DWH befinden. Default ist der 31.12.9999',
	DAT_VON_ALT DATE COMMENT 'Nur bei Umzugsfilialen gefuellt: Das dat_von der Vorgaenger-Filiale',
	DAT_EROEFFNUNG_ALT DATE COMMENT 'Nur bei Umzugsfilialen gefuellt: Das Eroeffnungsdatum der Vorgaenger-Filiale',
	UMZUGSFILIALE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist = 1 bei geschlossenen Filialen, fuer die eine Nachfolger-Filiale existiert. Sonst = 0',
	GF_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Geschaeftsfuehrer ID, numerisch. Wird hierzur Performancesteigerung denormalisiert abgelegt, um den Join zur VKL-Tabelle zu ersparen',
	UMSATZ_EA_EUR NUMBER(18,2) DEFAULT 0 COMMENT 'Umsatz laut Expansionsauftrag pro Jahr in Euro - Wert wird manuell gepflegt, da keinne SST zur Expansionsdatenbank besteht',
	UMSATZ_EA_LAND NUMBER(18,2) DEFAULT 0 COMMENT 'Umsatz laut Expansionsauftrag pro Jahr in Landeswaehrung - Wert wird manuell gepflegt, da keinne SST zur Expansionsdatenbank besteht. Umrechnung ueber Kurstabelle vom Anwender nicht erwuenscht.',
	BREITENGRAD NUMBER(38,16) COMMENT 'Breitengrad aus dem GIS-System (Latitude)',
	LAENGENGRAD NUMBER(38,16) COMMENT 'Laengengrad aus dem GIS-System (Longitude)',
	GIS_QUALI_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Numerische ID des GIS Qualitaetskennzeichens. ',
	GLN_ID VARCHAR(80) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Global Location Number - international  eindeutige Kennzeichnung der Lokation. Quelle ist KNA1 (Retail) mit den Feldern bbbnr(Basisnummer), bbsnr(Individueller Nummernteil) und bubkz(Pruefziffer)',
	FIPO_PRUEF_OBJEKT_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'eindeutige ID eines Pruefobjekts aus dem Quellfeld pob_id',
	ADRESSE_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Adressnummer aus dem Quellfeld adrnr. Referenz zur SAP Tabelle adrc (im DWH nicht vorhanden)',
	DAT_DAYFORCE_AB DATE NOT NULL DEFAULT CAST('9999-12-31' AS DATE) COMMENT 'Datum, ab dem die Personaldaten aus',
	MANDANT_ID_URSPRUNG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'urspruengliche Mandant ID DWH bezueglich des Liefersystem (SAP) - Bsp. Moldau wird im SAP-System Rumaenien verwaltet, deshalb wird in diesem Feld die Mandant ID von Rumaenien gespeichert',
	EIGENTUM_MIETE_KZ VARCHAR(4) COLLATE 'en-ci' COMMENT 'Kennzeichen, ob es sich bei der Filiale um Eigentum (=E) oder Mietobjekt (=M) handelt (kann auch null sein, wenn nicht definiert)',
	DAT_LETZTE_MODERNISIERUNG_VON DATE COMMENT 'Datum Start letzte Modernisierungsmaßnahme (Format JJJJ-MM-TT)',
	DAT_LETZTE_MODERNISIERUNG_BIS DATE COMMENT 'Datum Ende letzte Modernisierungsmaßnahme (Format JJJJ-MM-TT)',
	DAT_LETZTER_FACELIFT DATE COMMENT 'Datum Start letzter Facelift (Format JJJJ-MM-TT)',
	DAT_WIEDEREROEFFNUNG DATE COMMENT 'Datum der Wiedereroeffnung bei Abriss/Neubau, bei denen die Marktnummer gleich bleibt (Datum wird manuell gepflegt, da keine Quelle)',
	EINWOHNER_ANZAHL NUMBER(38,0) COMMENT 'Einwohner je Markt. Manuelle Befuellung',
	UMSATZ_ERWARTUNG_EUR NUMBER(18,2) COMMENT 'Umsatz Erwartung je Markt. Manuelle Befuellung',
	DAT_LETZTER__FACELIFT_VON DATE COMMENT 'Datum des letzten Facelifts des Marktes. Manuelle Befuellung',
	TD_UPDATE TIMESTAMP_LTZ(9),
	TD_INSERT TIMESTAMP_LTZ(9),
	FILIALTYP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Filialtypisierung fuer Sortimentskonzept. (VT Orga INT). Wird jaehrlich manuell aktualisiert.',
	unique (WUP_ID, MANDANT_ID)
);